fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let n = numbers.len();
    
    // Handle empty input case
    if n == 0 {
        return Vec::new();
    }
    
    // Calculate output size: 2n - 1
    let output_size = 2 * n - 1;
    let mut result = Vec::with_capacity(output_size);
    
    // Iterate through numbers, adding number then delimiter (except last)
    for (i, &num) in numbers.iter().enumerate() {
        result.push(num);
        
        // Add delimiter after each element except the last one
        if i < n - 1 {
            result.push(delim);
        }
    }
    
    result
}